Give the correct way to remove elements from a <code>std::vector</code>, a <code>std::map</code> and a <code>std::unordered_map</code> while filtering. What does the snippet print?<br><pre><code>#include &lt;algorithm&gt;
#include &lt;iostream&gt;
#include &lt;map&gt;
#include &lt;string&gt;
#include &lt;unordered_map&gt;
#include &lt;vector&gt;

int main() {
    // A: erase(it) returns the iterator to the next element
    std::vector&lt;int&gt; a{1, 2, 3, 4, 5, 6};
    for (auto it = a.begin(); it != a.end(); ) {
        if (*it % 2 == 0) it = a.erase(it);
        else ++it;
    }
    for (int x : a) std::cout &lt;&lt; x &lt;&lt; ' ';
    std::cout &lt;&lt; '\n';

    // B: erase-remove idiom (pre-C++20)
    std::vector&lt;int&gt; b{1, 2, 3, 4, 5, 6};
    b.erase(std::remove_if(b.begin(), b.end(), [](int x) { return x % 2 == 0; }), b.end());
    for (int x : b) std::cout &lt;&lt; x &lt;&lt; ' ';
    std::cout &lt;&lt; '\n';

    // C: C++20 std::erase_if works on vector, deque, list, map, unordered_map, set, string
    std::vector&lt;int&gt; c{1, 2, 3, 4, 5, 6};
    std::erase_if(c, [](int x) { return x % 2 == 0; });
    for (int x : c) std::cout &lt;&lt; x &lt;&lt; ' ';
    std::cout &lt;&lt; '\n';

    // map: erase(it) also returns the next iterator
    std::map&lt;int, std::string&gt; m{{1, "a"}, {2, "b"}, {3, "c"}};
    for (auto it = m.begin(); it != m.end(); ) {
        if (it-&gt;first == 2) it = m.erase(it);
        else ++it;
    }
    for (const auto&amp; [k, s] : m) std::cout &lt;&lt; k &lt;&lt; s &lt;&lt; ' ';
    std::cout &lt;&lt; '\n';

    std::unordered_map&lt;int, int&gt; u{{1, 10}, {2, 20}, {3, 30}, {4, 40}};
    std::size_t removed = std::erase_if(u, [](const auto&amp; kv) { return kv.second &gt; 25; });
    std::cout &lt;&lt; "unordered removed " &lt;&lt; removed &lt;&lt; ", left " &lt;&lt; u.size() &lt;&lt; '\n';
}</code></pre>

How do you get the 99% VaR and the 99% expected shortfall from 10,000 scenario P&amp;Ls without sorting all of them? Code and output below (P&amp;L in GBP k).<br><pre><code>#include &lt;algorithm&gt;
#include &lt;cstdio&gt;
#include &lt;vector&gt;

int main() {
    // 10,000 scenario P&amp;Ls in GBP k: values -4999..5000 in a fixed permutation (7919 is coprime to 10000)
    std::vector&lt;double&gt; pnl(10000);
    for (int i = 0; i &lt; 10000; ++i) pnl[i] = (i * 7919) % 10000 - 4999.0;

    const std::size_t k = 100;                      // 1% of 10,000 = the 101st smallest P&amp;L is the 1% quantile
    std::nth_element(pnl.begin(), pnl.begin() + k, pnl.end());
    const double q1 = pnl[k];                       // value at 1% quantile: 101st worst outcome
    double tail = 0.0;
    for (std::size_t i = 0; i &lt; k; ++i) tail += pnl[i];   // the 100 worst strictly below the quantile
    std::printf("1%% quantile P&amp;L = %.1f k\n", q1);
    std::printf("99%% VaR = %.1f k\n", -q1);
    std::printf("99%% ES  = %.1f k\n", -tail / k);
}</code></pre>

Pillar times of a zero curve are t = {0.25, 0.5, 1, 2, 5, 10} years. For x = 0.5, what do <code>lower_bound</code> and <code>upper_bound</code> return, and how do you find the bracketing segment for linear interpolation? Output below.<br><pre><code>#include &lt;algorithm&gt;
#include &lt;iostream&gt;
#include &lt;vector&gt;

// index i with t[i] &lt;= x &lt; t[i+1], clamped to a valid segment
std::size_t bracket(const std::vector&lt;double&gt;&amp; t, double x) {
    auto ub = std::upper_bound(t.begin(), t.end(), x);
    std::size_t i = static_cast&lt;std::size_t&gt;(ub - t.begin());
    i = (i == 0) ? 0 : i - 1;
    return std::min(i, t.size() - 2);
}

int main() {
    std::vector&lt;double&gt; t{0.25, 0.5, 1.0, 2.0, 5.0, 10.0};   // pillar times in years
    for (double x : {0.1, 0.5, 1.5, 10.0, 12.0}) {
        auto lb = std::lower_bound(t.begin(), t.end(), x);
        auto ub = std::upper_bound(t.begin(), t.end(), x);
        std::cout &lt;&lt; "x=" &lt;&lt; x &lt;&lt; "  lower_bound=" &lt;&lt; (lb - t.begin())
                  &lt;&lt; "  upper_bound=" &lt;&lt; (ub - t.begin())
                  &lt;&lt; "  bracket=" &lt;&lt; bracket(t, x) &lt;&lt; '\n';
    }
}</code></pre>

