How do you make Monte Carlo normals bit-reproducible across compilers, and what can still break reproducibility even after you do it? Code and output below.<br><pre><code>#include &lt;cmath&gt;
#include &lt;cstdio&gt;
#include &lt;random&gt;

// Uniform in (0,1) from the top 53 bits of the 64-bit engine output
double uniform01(std::mt19937_64&amp; g) {
    return ((g() &gt;&gt; 11) + 0.5) * (1.0 / 9007199254740992.0);   // 2^53
}

int main() {
    constexpr double pi = 3.14159265358979323846;
    std::mt19937_64 g(42);
    for (int i = 0; i &lt; 3; ++i) {
        double u1 = uniform01(g), u2 = uniform01(g);
        double z = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * pi * u2);   // Box-Muller
        std::printf("z %d: %.6f\n", i, z);
    }
}</code></pre>

